public static int findNthLeapYear(int Y, int N) {
    int count = 0;
    while (true) {
        Y++;
        if (Y % 4 == 0 && Y % 100 != 0 || Y % 400 == 0) {
            count++;
            if (count == N) {
                return Y;
            }
        }
    }
}

