    if (grid == null) {
        return 0;
    }

    int numDeposits = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                numDeposits++;
            }
        }
    }

    return numDeposits;
}

