public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a 2D boolean array to keep track of visited n-tersections
    boolean[][] visited = new boolean[n][n];

    // Mark the starting n-tersection as visited
    visited[start[0]][start[1]] = true;

    // Perform BFS from the starting n-tersection
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    while (!queue.isEmpty()) {
        int[] current = queue.remove();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Explore all possible paths from the current n-tersection
        for (int[] neighbor : paths) {
            // Calculate the new coordinate
            int newX = current[0] + neighbor[0];
            int newY = current[1] + neighbor[1];

            // If the new coordinate is within the n-terresting space and has not been visited, mark it as visited and add it to the queue
            if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX][newY]) {
                visited[newX][newY] = true;
                queue.add(new int[] { newX, newY });
            }
        }
    }

    // If the ending n-tersection has not been reached, return "cannot be travelled"
    return "cannot be travelled";
}

